#include <bits/stdc++.h>
using namespace std;

int main() {
    int t;
    cin>>t;
    while(t--)
    {
        int n,m;
        cin>>n>>m;
        vector<int>v;
        for(int i=0; i<m; i++)
        {
            int x;
            cin>>x;
            v.push_back(x);
        }
        sort(v.begin(),v.end());
        int x=min(v[0]-1,n-v[m-1]);
        int ans=2*x;
        int s=0;
        if(x==v[0]-1)
        {
            for(int i=0; i<m-1; i++)
            {
                if(i+1<m && v[i]+1==v[i+1])
                {
                    continue;
                }
                else{
                    
                    s=max(v[i+1]-(v[i]+1+x),s);
                }
                
            }
            s=max(n-(v[m-1]),s);
        }
        else{
            for(int i=0; i<m-1; i++)
            {
                if(i+1<m && v[i]+1==v[i+1])
                    continue;
                else
                    s=max(v[i+1]-(v[i]+1+x),s);
                    
            }
            s=max(v[m-1]-1,s);
            
        }
        
        
        cout<<s+ans<<endl;
    }
    return 0;
}
